findings.codeql_raw_query:
/**
 * @name Insecure parsing patterns in config files
 * @description Configuration parsing could allow code injection through eval-like operations
 * @kind problem
 * @problem.severity warning
 * @id py/insecure-parsing
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.DataFlow

from DataFlow::CallCfgNode call, DataFlow::ExprNode arg
where
  // Look for calls that could parse expressions or execute code
  (
    // Built-in eval/exec
    call = API::builtin(["eval", "exec"]).getACall() or
    // ast.literal_eval could be safe but check anyway
    call = API::moduleImport("ast").getMember("literal_eval").getACall() or
    // configparser might have interpolation issues
    call = API::moduleImport("configparser").getMember(["get", "getint", "getfloat", "getboolean"]).getACall() or
    // JSON parsing (could have code injection if used with object_hook)
    call = API::moduleImport("json").getMember(["load", "loads"]).getACall() or
    // pickle is always dangerous
    call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall() or
    // yaml can be dangerous
    call = API::moduleImport("yaml").getMember(["load", "unsafe_load"]).getACall()
  )
select call, "Potential insecure parsing operation that could lead to code execution if parsing untrusted input."
